const response = $input.first().json;
const rawText = response.content[0].text;

let article;
try {
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  article = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Impossible de parser la réponse Claude en JSON. Réponse brute : ' + rawText.substring(0, 500));
}

if (!article.titre_seo || !article.contenu_html || !article.slug) {
  throw new Error('Réponse Claude incomplète — champs manquants');
}

const prevData = $('Lire sujet suivant').first().json;
const subject = {
  ...prevData,
  categorie_id: parseInt(prevData.categorie_id),
  mots_cles_secondaires: prevData.mots_cles_secondaires.split(',').map(s => s.trim())
};

return [{ json: { article, subject, filePath: '' } }];

const response = $input.first().json;
const b64 = response.data[0].b64_json;

// Parser réponse Claude est un ancêtre direct dans le flux
const prevData = $('Parser réponse Claude').first().json;

if (!prevData || !prevData.article) {
  throw new Error('Données Parser réponse Claude introuvables. Items disponibles: ' + JSON.stringify($input.all().map(i => Object.keys(i.json))));
}

return [{
  json: {
    article: prevData.article,
    subject: prevData.subject,
    allSubjects: prevData.allSubjects,
    filePath: prevData.filePath
  },
  binary: {
    data: {
      data: b64,
      mimeType: 'image/png',
      fileExtension: 'png',
      fileName: prevData.article.slug + '.png'
    }
  }
}];

const mediaId = parseInt($input.first().json.id);
const articleData = $('Extraire image base64').first().json;
const article = articleData.article;
const subject = articleData.subject;

// Forcer le slug = mot-clé principal normalisé
const motCle = subject.mot_cle_principal || article.slug;
const wpSlug = motCle
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-');

// JSON-LD Article schema
const jsonLd = `<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "Article",
  "headline": "${article.titre_seo}",
  "description": "${article.meta_description}",
  "author": {
    "@type": "Organization",
    "name": "Calymia"
  },
  "publisher": {
    "@type": "Organization",
    "name": "Calymia",
    "url": "https://www.calymia.com"
  },
  "mainEntityOfPage": {
    "@type": "WebPage",
    "@id": "https://www.calymia.com/blog/${wpSlug}"
  }
}
</script>`;

// Injecter le JSON-LD avant le contenu
const wpContent = jsonLd + article.contenu_html;

const wpBodyObj = {
  title: article.titre_seo,
  content: wpContent,
  slug: wpSlug,
  status: 'draft',
  featured_media: mediaId,
  categories: [parseInt(subject.categorie_id)],
  author: 3
};

return [{
  json: {
    mediaId,
    article,
    subject,
    allSubjects: articleData.allSubjects,
    filePath: articleData.filePath,
    wpTitle: wpBodyObj.title,
    wpContent: wpBodyObj.content,
    wpSlug: wpBodyObj.slug,
    wpStatus: 'draft',
    wpFeaturedMedia: mediaId,
    wpCategories: [parseInt(subject.categorie_id)],
    wpAuthor: 2
  }
}];

const postId = $input.first().json.id;
const postStatus = $input.first().json.status;
const prevData = $('Préparer payload WordPress').first().json;

return [{
  json: {
    id: prevData.subject.id,
    postId: postId,
    postStatus: postStatus,
    postLink: 'https://www.calymia.com/?p=' + postId,
    postTitle: prevData.article.titre_seo,
    categorie: prevData.subject.categorie,
    statut: 'done',
    wp_post_id: postId,
    date_publication: new Date().toISOString().split('T')[0]
  }
}];

const data = $('Marquer sujet done').first().json;
return [{
  json: {
    success: true,
    message: 'Article créé avec succès. Statut : ' + data.postStatus,
    postId: data.postId,
    postStatus: data.postStatus,
    postTitle: data.postTitle,
    postLink: data.postLink
  }
}];

const wpPost = $input.first().json;
const wpTitle = $('Préparer payload WordPress').first().json.wpTitle;
const metaDesc = $('Extraire image base64').first().json.article.meta_description;
const motCle = $('Lire sujet suivant').first().json.mot_cle_principal;
const motsClesSecondaires = $('Lire sujet suivant').first().json.mots_cles_secondaires || '';
const mediaId = $('Préparer payload WordPress').first().json.wpFeaturedMedia;

const normalizeText = (str) => str
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s,]/g, '')
  .trim();

const tousMotsCles = normalizeText(motCle + ',' + motsClesSecondaires);

const seopressBody = JSON.stringify({
  meta: {
    _seopress_titles_title: wpTitle,
    _seopress_titles_desc: metaDesc,
    _seopress_analysis_target_kw: tousMotsCles
  }
});

const mediaBody = JSON.stringify({
  alt_text: motCle
});

return [{ json: { 
  postId: wpPost.id,
  mediaId,
  seopressBody,
  mediaBody,
  wpTitle,
  metaDesc,
  motCle
}}];

const articles = $input.all();
const sujet = $('Lire sujet suivant').first().json;

// Gérer le cas où il n'y a aucun article publié
if (!articles || articles.length === 0 || !articles[0].json || !articles[0].json.title) {
  return [{ json: { 
    ...sujet,
    articlesPublies: '',
    articlesCount: 0
  }}];
}

// Utiliser le lien complet retourné par l'API WordPress
const articlesList = articles
  .filter(a => a.json && a.json.link && a.json.title)
  .map(a => {
    const link = a.json.link || '';
    const title = a.json.title ? a.json.title.rendered : '';
    return `- ${title} : ${link}`;
  })
  .join('\n');

return [{ json: { 
  ...sujet,
  articlesPublies: articlesList,
  articlesCount: articles.length
}}];
